// V2 drawing revision: type-specific cabinet symbols and manually entered interface geometry.
const interfaceDefaults={fresh:['新风入口','左端',900,700],return:['回风入口','上方',800,600],mix:['混风入口','上方',700,500],supply:['送风出口','右端',900,700],primary:['无接口','无',0,0],medium:['无接口','无',0,0],high:['无接口','无',0,0],coil:['冷水接管','右侧',80,80],heat:['热水接管','右侧',80,80],humid:['加湿介质','右侧',50,50],fan:['送风出口','右端',900,700],silencer:['无接口','无',0,0],access:['无接口','无',0,0],empty:['无接口','无',0,0]};
function ensureGeometry(s){if(s.isFormalSegment||s.interfaceName!==undefined)return;const d=interfaceDefaults[s.type]||['待定义接口','右侧',100,100],values={interfaceName:d[0],portSide:d[1],portWidth:d[2],portHeight:d[3],doorSide:['primary','medium','high','coil','fan','access'].includes(s.type)?'检修侧':'无'};s.__displayGeometryDefaults||=[];Object.entries(values).forEach(([key,value])=>{if(s[key]===undefined){s[key]=value;s.__displayGeometryDefaults.push(key)}});}
function symbol(type){switch(type){
 case 'fresh':return '<path class="symbol" d="M12 50 H77 M62 35 L77 50 L62 65"/><path class="symbol" d="M25 20 V80"/>';
 case 'return':return '<path class="symbol" d="M50 10 V52 H82 M67 37 L82 52 L67 67"/><path class="symbol" d="M20 22 H50"/>';
 case 'supply':return '<path class="symbol" d="M16 50 H86 M69 32 L86 50 L69 68"/><path class="symbol" d="M78 20 V80"/>';
 case 'mix':return '<path class="symbol" d="M12 18 L50 50 L12 82 M88 18 L50 50 L88 82"/><circle class="symbol-fill" cx="50" cy="50" r="6"/>';
 case 'primary':return '<rect class="symbol" x="24" y="15" width="52" height="70"/><path class="symbol" d="M24 15 L76 85 M24 50 L59 85 M41 15 L76 50"/>';
 case 'medium':return '<rect class="symbol" x="20" y="15" width="60" height="70"/><path class="symbol" d="M20 15 L80 85 M20 39 L65 85 M35 15 L80 65 M20 61 L44 85 M56 15 L80 39"/>';
 case 'high':return '<rect class="symbol" x="17" y="15" width="66" height="70"/><path class="symbol" d="M17 15 L83 85 M17 31 L70 85 M17 49 L52 85 M31 15 L83 69 M49 15 L83 51 M67 15 L83 33"/>';
 case 'coil':return '<rect class="symbol" x="20" y="16" width="60" height="68"/><path class="symbol" d="M24 26 H76 M24 38 H76 M24 50 H76 M24 62 H76 M24 74 H76"/><circle class="symbol-fill" cx="82" cy="26" r="5"/><circle class="symbol-fill" cx="82" cy="74" r="5"/>';
 case 'heat':return '<rect class="symbol" x="20" y="16" width="60" height="68"/><path class="symbol" d="M25 28 H75 M25 45 H75 M25 62 H75 M32 77 Q26 70 32 64 M50 77 Q44 70 50 64 M68 77 Q62 70 68 64"/><circle class="symbol-fill" cx="82" cy="28" r="5"/><circle class="symbol-fill" cx="82" cy="62" r="5"/>';
 case 'fan':return '<circle class="symbol" cx="50" cy="50" r="33"/><circle class="symbol-fill" cx="50" cy="50" r="6"/><path class="symbol" d="M50 44 C70 22 80 35 66 48 M56 52 C75 66 65 82 51 65 M46 55 C22 70 19 49 42 48"/>';
 case 'humid':return '<path class="symbol" d="M20 74 H80 M30 74 V35 M50 74 V27 M70 74 V35"/><path class="symbol" d="M30 30 Q25 18 35 14 M50 22 Q45 10 55 6 M70 30 Q65 18 75 14"/>';
 case 'silencer':return '<path class="symbol" d="M22 20 V80 M40 14 V86 M60 14 V86 M78 20 V80"/>';
 case 'access':return '<rect class="door" x="26" y="13" width="48" height="74"/><circle class="symbol-fill" cx="67" cy="50" r="3"/>';
 case 'empty':return '<path class="symbol" d="M22 78 L78 22"/>';
 default:return '<path class="symbol" d="M20 20 H80 V80 H20 Z"/>';
}}
function portDrawing(s,x,y,w,h){if(!s||typeof s!=='object')return '';ensureGeometry(s);if(s.portSide==='无'||Number(s.portWidth)<=0||Number(s.portHeight)<=0)return '';const pw=Math.max(9,Math.min(w-6,Number(s.portWidth)/Math.max(1,Number(s.length))*w)),ph=Math.max(9,Math.min(h-6,Number(s.portHeight)/2300*h));let px=x+w/2-pw/2,py=y+h/2-ph/2,arrow='';if(s.portSide==='上方'){py=y-5;arrow=`M${x+w/2} ${y-20} V${y-5}`}else if(s.portSide==='下方'){py=y+h-ph+5;arrow=`M${x+w/2} ${y+h+20} V${y+h+5}`}else if(s.portSide==='左端'){px=x-5;arrow=`M${x-21} ${y+h/2} H${x-5}`}else if(s.portSide==='右端'){px=x+w-pw+5;arrow=`M${x+w+21} ${y+h/2} H${x+w+5}`}else if(s.portSide==='左侧'){px=x+5;arrow=`M${x+pw+24} ${y+h/2} H${x+pw+5}`}else{px=x+w-pw-5;arrow=`M${x+w-pw-23} ${y+h/2} H${x+w-pw-5}`}return `<rect class="port" x="${px}" y="${py}" width="${pw}" height="${ph}"/><path class="port-line" d="${arrow}"/>`}
function projection(which,mini=false){const total=Math.max(1,segments.reduce((n,s)=>n+Math.max(0,Number(s.length)||0),0)),selected=segments.find(s=>s.id===selectedId),end=['front','rear','end'].includes(which),top=['top','bottom'].includes(which),reverse=['rear','right','bottom'].includes(which);let parts='';if(end){parts+='<rect class="body" x="325" y="44" width="250" height="200"/><rect class="edge" x="340" y="59" width="220" height="170"/>';const opening=segments.find(s=>s.portSide==='左端'||s.portSide==='右端');if(opening){ensureGeometry(opening);const ow=Math.min(190,Math.max(25,Number(opening.portWidth)/2500*220)),oh=Math.min(145,Math.max(20,Number(opening.portHeight)/2300*170));parts+=`<rect class="port" x="${450-ow/2}" y="${144-oh/2}" width="${ow}" height="${oh}"/>`}parts+='<path class="air" d="M390 144 H505"/>';}
else{const x=55,y=top?80:63,w=790,h=top?126:168;parts+=`<rect class="body" x="${x}" y="${y}" width="${w}" height="${h}"/><path class="edge" d="M${x+5} ${y+8} H${x+w-5} M${x+5} ${y+h-8} H${x+w-5}"/>`;if(!top)parts+=`<path class="edge" d="M${x} ${y+h+5} H${x+w} M${x+15} ${y+h+5} V${y+h+13} M${x+w-15} ${y+h+5} V${y+h+13}"/>`;let cursor=x;const ordered=reverse?[...segments].reverse():segments;ordered.forEach((s,i)=>{ensureGeometry(s);const width=Math.max(1,(Math.max(0,Number(s.length)||0)/total)*w);if(s.id===selectedId)parts+=`<rect class="selected-rect" x="${cursor}" y="${y}" width="${width}" height="${h}"/>`;parts+=`<line class="edge" x1="${cursor}" y1="${y}" x2="${cursor}" y2="${y+h}"/>`;if(width>18)parts+=`<g transform="translate(${cursor+width*.08} ${y+h*.12}) scale(${width*.84/100} ${h*.76/100})">${symbol(s.type)}</g>`;if(!mini&&width>38)parts+=`<text class="unit-label" x="${cursor+width/2}" y="${y+h+17}" text-anchor="middle">${String(segments.indexOf(s)+1).padStart(2,'0')} · ${Math.round(Number(s.length)||0)}</text>`;if(!mini&&s.doorSide!=='无'&&width>35)parts+=`<rect class="door" x="${cursor+width*.19}" y="${y+8}" width="${Math.max(12,width*.35)}" height="${Math.max(12,h*.53)}"/>`;if(!mini)parts+=portDrawing(s,cursor,y,width,h);cursor+=width});parts+=`<path class="air" d="M${reverse?x+w-35:x+28} ${y+h/2} H${reverse?x+28:x+w-35}"/>`;
if(!mini){parts+=`<path class="dim-line" d="M${x} 37 H${x+w} M${x} 29 V45 M${x+w} 29 V45"/><text x="450" y="31" text-anchor="middle">L ${total} mm</text><path class="dim-line" d="M27 ${y} V${y+h} M19 ${y} H35 M19 ${y+h} H35"/><text x="18" y="${y+h/2}" text-anchor="middle" transform="rotate(-90 18 ${y+h/2})">${top?'W 2500':'H 2300'} mm</text>`;if(selected){const label=`${selected.interfaceName} · ${selected.portSide} · ${selected.portWidth} × ${selected.portHeight} mm`;parts+=`<text x="450" y="${y+h+43}" text-anchor="middle">当前段接口：${escapeHtml(label)}</text>`}}}
const label=which==='side'?'侧视':which==='top'?'俯视':which==='end'?'端视':which==='front'?'前面':which==='rear'?'后面':which==='left'?'左面':which==='right'?'右面':which==='bottom'?'底面':which;return `<svg viewBox="0 0 900 300" role="img" aria-label="${label}箱体外貌及功能段专用示意"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8 Z" fill="#1196a8"/></marker><marker id="portArrow" markerWidth="7" markerHeight="7" refX="5" refY="3.5" orient="auto"><path d="M0 0 L7 3.5 L0 7 Z" fill="#b2762e"/></marker></defs>${parts}</svg>`}
renderView=function(){const area=$('viewArea');if(view==='six'){area.innerHTML=`<div class="six-grid">${[['front','前面'],['rear','后面'],['left','左面'],['right','右面'],['top','顶面'],['bottom','底面']].map(([key,label])=>`<div class="face"><span>${label}</span>${projection(key,true)}</div>`).join('')}</div>`}else area.innerHTML=projection(view,false)};
renderInputs=function(){const s=segments.find(x=>x.id===selectedId);$('inputTitle').textContent=s?`${formalReadonly?'正式项目只读':'功能段输入项'} · ${s.name}`:'功能段输入项';if(!s){$('inputGrid').innerHTML='<span class="view-label">选择中央功能段后编辑输入</span>';$('confirmSegment').disabled=true;return}if(formalReadonly){$('inputGrid').innerHTML=`<span class="view-label">V2 稳定段 ID：${escapeHtml(s.id)}</span><span class="view-label">正式段类型：${escapeHtml(s.sourceType)}</span><span class="view-label">型号：${escapeHtml(s.model)||'未录入'}</span><span class="view-label">零件 ID：${escapeHtml(s.partRef?.partId)||'未关联'}</span>`;$('confirmSegment').disabled=true;return}ensureGeometry(s);const options=['无','左端','右端','上方','下方','左侧','右侧'];$('inputGrid').innerHTML=`<label class="field"><span>功能段名称</span><input data-field="name" value="${escapeHtml(s.name)}"></label><label class="field"><span>段长 mm *</span><input data-field="length" type="number" min="1" value="${escapeHtml(s.length)}"></label><label class="field"><span>接口名称</span><input data-field="interfaceName" value="${escapeHtml(s.interfaceName)}"></label><label class="field"><span>接口方向 / 所在面</span><select data-field="portSide">${options.map(x=>`<option ${s.portSide===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field"><span>接口宽 mm</span><input data-field="portWidth" type="number" min="0" value="${escapeHtml(s.portWidth)}"></label><label class="field"><span>接口高 mm</span><input data-field="portHeight" type="number" min="0" value="${escapeHtml(s.portHeight)}"></label><label class="field"><span>检修方向</span><select data-field="doorSide">${['无','检修侧','反侧'].map(x=>`<option ${s.doorSide===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field"><span>人工选定型号</span><input data-field="model" value="${escapeHtml(s.model)}" placeholder="未填写"></label><label class="field"><span>选型来源 *</span><input data-field="source" value="${escapeHtml(s.source)}"></label><label class="field"><span>人工能力 kW</span><input data-field="capacity" value="${escapeHtml(s.capacity)}" placeholder="未填写"></label><label class="field"><span>人工阻力 Pa</span><input data-field="resistance" value="${escapeHtml(s.resistance)}" placeholder="未填写"></label>${partPickerMarkup(s)}`;$('confirmSegment').disabled=false};
function formalInterfaceMarkup(segment){const connections=Array.isArray(segment.connections)?segment.connections:[];if(!connections.length)return `<div class="output-card"><h3>正式方案接口</h3><p class="result-empty">${segment.connectionsStatus==='none'?'正式数据明确标记为无接口。':'正式数据未提供接口记录。'}</p></div>`;return `<div class="output-card"><h3>正式方案接口 · ${connections.length} 项</h3><dl>${connections.map(connection=>`<dt>${escapeHtml(connection.name||'未命名接口')} · ${escapeHtml(connection.face||'所在面未提供')}</dt><dd>${connection.width==null||connection.width===''?'未提供':escapeHtml(connection.width)} × ${connection.height==null||connection.height===''?'未提供':escapeHtml(connection.height)} mm</dd><dt>定位坐标</dt><dd>${['x','y','z'].filter(axis=>connection[axis]!=null&&connection[axis]!=='').map(axis=>`${axis.toUpperCase()} ${escapeHtml(connection[axis])}`).join(' · ')||'未提供'}</dd>`).join('')}</dl></div>`}
function professionalSelectionLinks(segment){const links=[];if(['primary','medium','high'].includes(segment.type))links.push({action:'filter',label:'启动过滤器专业选型'});const actualCooling=segment.type==='coil'&&(!segment.sourceType||segment.sourceType==='cooling-coil');if(actualCooling)links.push({action:'coil',label:'启动盘管专业选型'});return links}
function professionalManagementMarkup(segment){const links=professionalSelectionLinks(segment),actions=links.map(link=>link.action?`<button type="button" data-professional-action="${link.action}">${link.label}</button>`:`<a href="${link.href}">${link.label}</a>`).join('');return `<section class="professional-card" aria-label="专业选型管理"><h3>选型原则与专业管理</h3><span class="workflow-state">${links.length?'可进入对应专业模块':'本段暂无独立专业模块'}</span><p>这里维护段结构与人工录入。过滤器专业规则可通过新标签页执行；其他专业模块仍为人工录入。</p><div class="professional-actions">${actions}</div></section>`}
renderOutputs=function(){const s=segments.find(x=>x.id===selectedId);if(!s){$('outputScroll').innerHTML='<p class="result-empty">选择功能段后展示当前段输出。</p>';return}const index=segments.indexOf(s)+1;if(formalReadonly){$('outputScroll').innerHTML=`<div class="output-card"><h3>${String(index).padStart(2,'0')} ${escapeHtml(s.name)} · 正式保存方案</h3><dl><dt>项目 / 机组</dt><dd>${escapeHtml(formalInfo.projectName)} / ${escapeHtml(formalInfo.unitNo)}</dd><dt>稳定段 ID</dt><dd>${escapeHtml(s.id)}</dd><dt>稳定段类型</dt><dd>${escapeHtml(s.sourceType)}</dd><dt>段长</dt><dd>${escapeHtml(s.length)} mm</dd><dt>箱体宽</dt><dd>${formalInfo.width===null?'未提供':escapeHtml(formalInfo.width)+' mm'}</dd><dt>箱体高</dt><dd>${formalInfo.height===null?'未提供':escapeHtml(formalInfo.height)+' mm'}</dd><dt>已选型号</dt><dd>${escapeHtml(s.model)||'未录入'}</dd><dt>关联零件 ID</dt><dd>${escapeHtml(s.partRef?.partId)||'未关联'}</dd></dl></div>${formalInterfaceMarkup(s)}<div class="output-note">只读载入自正式工作台已保存项目。缺失的截面或接口数据标为“未提供”；模型中的示意尺寸不会作为正式数据。此视图不写回项目、不执行专业计算。</div><div class="professional-card"><h3>正式项目管理</h3><span class="workflow-state">V2 保存快照 · 只读</span><p>原 V2 项目保持只读；来源及只读状态见本页项目说明。</p></div>`;return}ensureGeometry(s);$('outputScroll').innerHTML=`<div class="output-card"><h3>${String(index).padStart(2,'0')} ${escapeHtml(s.name)} · 结构输出</h3><dl><dt>状态</dt><dd>${s.confirmed?'已确认':'待确认'}</dd><dt>段长</dt><dd>${escapeHtml(s.length)} mm</dd><dt>接口名称</dt><dd>${escapeHtml(s.interfaceName)||'未填写'}</dd><dt>接口方向</dt><dd>${escapeHtml(s.portSide)}</dd><dt>接口大小</dt><dd>${escapeHtml(s.portWidth)} × ${escapeHtml(s.portHeight)} mm</dd><dt>检修方向</dt><dd>${escapeHtml(s.doorSide)}</dd></dl></div><div class="output-card"><h3>人工选型输出</h3><dl><dt>型号</dt><dd>${escapeHtml(s.model)||'未填写'}</dd><dt>能力</dt><dd>${escapeHtml(s.capacity)?escapeHtml(s.capacity)+' kW':'未录入'}</dd><dt>阻力</dt><dd>${escapeHtml(s.resistance)?escapeHtml(s.resistance)+' Pa':'未录入'}</dd><dt>来源</dt><dd>${escapeHtml(s.source)||'未填写'}</dd></dl></div><div class="output-note">图中的接口位置与大小由下方输入项驱动。此处只呈现录入结果，不进行选型性能计算。</div>${professionalManagementMarkup(s)}`};
const oldRenderAll=renderAll;renderAll=function(){segments.forEach(ensureGeometry);oldRenderAll()};
$('inputGrid').addEventListener('change',e=>{if(e.target.tagName!=='SELECT')return;const s=segments.find(x=>x.id===selectedId);if(!s)return;if(e.target.dataset.partRef){const part=readEditedPartLibrary().find(item=>item.id===e.target.value);s.partRef=part?{partId:part.id,name:part.name||'',model:part.model||'',librarySchemaVersion:2,updatedAt:new Date().toISOString()}:{partId:'',name:'',model:'',librarySchemaVersion:2,updatedAt:null};if(part?.model)s.model=part.model;s.source=part?'3D零件库':s.source;persistSegmentPartRefs()}else if(e.target.dataset.field)s[e.target.dataset.field]=e.target.value;else return;s.confirmed=false;renderSegments();renderInputs();renderOutputs();renderView();$('inputNotice').textContent='输入已修改，需重新确认本段'});
segments.forEach(ensureGeometry);renderAll();
